    if (nums == null || nums.length == 0) {
        return res;
    }
    backtrack(nums, 0, res);
    return res;
}

private void backtrack(int[] nums, int idx, List<List<Integer>> res) {
    if (idx == nums.length) {
        List<Integer> current = new ArrayList<>();
        for (int num : nums) {
            current.add(num);
        }
        res.add(current);
        return;
    }
    for (int i = idx; i < nums.length; i++) {
        swap(nums, idx, i);
        backtrack(nums, idx + 1, res);
        swap(nums, idx, i);
    }
}

