    List<List<Integer>> res = new ArrayList<>();
    if (nums == null || nums.length == 0) {
        res.add(new ArrayList<>());
        return res;
    }
    class Backtracker {
        void backtrack(int idx, boolean[] used, List<Integer> path) {
            if (idx == nums.length) {
                res.add(new ArrayList<>(path));
                return;
            }
            for (int i = 0; i < nums.length; i++) {
                if (used[i]) continue;
                used[i] = true;
                path.add(nums[i]);
                backtrack(idx + 1, used, path);
                path.remove(path.size() - 1);
                used[i] = false;
            }
        }
    }
    Backtracker bt = new Backtracker();
    bt.backtrack(0, new boolean[nums.length], new ArrayList<>());
    return res;
}

