public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null || start.length != end.length) {
        return "cannot be travelled";
    }
    java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();
    int dim = start.length;
    for (int i = 0; i < paths.length; i++) {
        int[] path = paths[i];
        if (path == null || path.length != 2 * dim) {
            continue; // invalid path, skip
        }
        int[] coordA = java.util.Arrays.copyOfRange(path, 0, dim);
        int[] coordB = java.util.Arrays.copyOfRange(path, dim, 2 * dim);
        String keyA = java.util.Arrays.toString(coordA);
        String keyB = java.util.Arrays.toString(coordB);
        graph.computeIfAbsent(keyA, k -> new java.util.ArrayList<>()).add(keyB);
        graph.computeIfAbsent(keyB, k -> new java.util.ArrayList<>()).add(keyA);
    }
    String startKey = java.util.Arrays.toString(start);
    String endKey = java.util.Arrays.toString(end);
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }
