public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null || start.length < 2 || end.length < 2)
        return "cannot be travelled";
    int sx = start[0], sy = start[1], ex = end[0], ey = end[1];
    if (sx == ex && sy == ey) return "can be travelled";
    if (sx < 0 || sx >= n || sy < 0 || sy >= n || ex < 0 || ex >= n || ey < 0 || ey >= n)
        return "cannot be travelled";

    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    for (int[] p : paths) {
        if (p == null || p.length != 4) continue;
        int x1 = p[0], y1 = p[1], x2 = p[2], y2 = p[3];
        if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n || x2 < 0 || x2 >= n || y2 < 0 || y2 >= n)
            continue;
        String key1 = x1 + "," + y1;
        String key2 = x2 + "," + y2;
        adj.computeIfAbsent(key1, k -> new java.util.ArrayList<>()).add(key2);
        adj.computeIfAbsent(key2, k -> new java.util.ArrayList<>()).add(key1);
    }

    java.util.Set<String> visited = new java.util.HashSet<>();
    java.util.Queue<String> queue = new java.util.LinkedList<>();
    String startKey = sx + "," + sy;
    String endKey = ex + "," + ey;
    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String cur = queue.poll();
        if (cur.equals(endKey)) return "can be travelled";
        java.util.List<String> neighbors = adj.get(cur);
        if (neighbors == null) continue;
        for (String nb : neighbors) {
            if (visited.add(nb)) {
                queue.add(nb);
            }
        }
    }
    return "cannot be travelled";
}

public static String appx(String word1, String word2) {
    // Create sets of unique characters for each word
    java.util.Set<Character> set1 = new java.util.HashSet<>();
    for (int i = 0; i < word1.length(); i++) {
        set1.add(word1.charAt(i));
    }
    java.util.Set<Character> set2 = new java.util.HashSet<>();
    for (int i = 0; i < word2.length(); i++) {
        set2.add(word2.charAt(i));
    }
    // Intersection size: unique common letters
    java.util.Set<Character> inter = new java.util.HashSet<>(set1);
    inter.retainAll(set2);
    int common = inter.size();

    int numerator = 2 * common;
    int denominator = word1.length() + word2.length();

    // Handle zero result
    if (numerator == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    // Reduce fraction
    int g = gcd(numerator, denominator);
    int numRed = numerator / g;
    int denRed = denominator / g;

    // If it simplifies to 1
    if (numRed == denRed) {
        return "appx(" + word1 + ", " + word2 + ") = 1";
    }

    return "appx(" + word1 + ", " + word2 + ") = " + numRed + "/" + denRed;
}

private static int gcd(int a, int b) {
    while (b != 0) {
        int t = b;
        b = a % b;
        a = t;
    }
    return a;
}

public static String convertDatesToWeekdays(String date) {
    // Split the input string into month, day, and year components
    String[] parts = date.trim().split("\\s+");
    int month = Integer.parseInt(parts[0]);   // 1-12
    int day   = Integer.parseInt(parts[1]);   // 1-31
    int year  = Integer.parseInt(parts[2]);   // e.g., 1997

    // Map month number to month name
    String[] monthNames = {"January","February","March","April","May","June",
                           "July","August","September","October","November","December"};
    String monthName = monthNames[month - 1];

    // Determine the day of the week using Calendar
    java.util.Calendar cal = java.util.Calendar.getInstance();
    cal.setLenient(false);
    cal.set(year, month - 1, day); // Calendar month is 0-based
    int dayOfWeekIndex = cal.get(java.util.Calendar.DAY_OF_WEEK); // 1=Sunday, 7=Saturday

    // Map Calendar's day of week to weekday name
    String[] dayNames = {"Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"};
    String dayName = dayNames[dayOfWeekIndex - 1];

    // Build the formatted result string
    return monthName + " " + day + ", " + year + " is a " + dayName;
}

public static String convertDatesToWeekdays(String date) {
    java.time.LocalDate ld = java.time.LocalDate.parse(date, java.time.format.DateTimeFormatter.ofPattern("MM dd yyyy"));
    String monthName = ld.getMonth().getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
    int day = ld.getDayOfMonth();
    int year = ld.getYear();
    String weekday = ld.getDayOfWeek().getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
    return String.format("%s %d, %d is a %s", monthName, day, year, weekday);
}

