public double trimMean(int[] arr) {
    int n = arr.length;
    if (n == 0) {
        return 0.0;
    }
    // number of elements to remove from each side (5% of n)
    int trim = n / 20; // floor of 5%
    java.util.Arrays.sort(arr);
    long sum = 0;
    for (int i = trim; i < n - trim; i++) {
        sum += arr[i];
    }
    double count = n - 2.0 * trim;
    return sum / count;
}

