public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) return false;
    int n = arr.length;
    if ((n & 1) == 1) return false; // odd length -> cannot pair all
    int[] freq = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k; // normalize remainder to [0, k-1]
        freq[r]++;
    }
    // Check remainder 0
    if ((freq[0] & 1) == 1) return false;
    // If k even, middle remainder must also pair with itself
    if ((k & 1) == 0) {
        int mid = k / 2;
        if ((freq[mid] & 1) == 1) return false;
    }
    // For all other remainders
    for (int r = 1; r <= k / 2; r++) {
        int complement = k - r;
        if (r == complement) continue; // already handled for even k case
        if (freq[r] != freq[complement]) return false;
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) return false;
    int n = arr.length;
    if (n % 2 != 0) return false; // cannot pair all elements

    int[] count = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k; // handle negative numbers
        count[r]++;
    }

    // remainder 0 must have an even count
    if (count[0] % 2 != 0) return false;

    // for each remainder r, count[r] must equal count[k - r]
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) { // this occurs when k is even and r = k/2
            if (count[r] % 2 != 0) return false;
            continue;
        }
        if (count[r] != count[k - r]) return false;
    }

    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0 || k <= 0) return false;
    int[] freq = new int[k];
    for (int num : arr) {
        int rem = ((num % k) + k) % k;
        freq[rem]++;
    }
    if (freq[0] % 2 != 0) return false;
    int half = k / 2;
    for (int r = 1; r <= half; r++) {
        if (r == k - r) { // k is even and r == k/2
            if (freq[r] % 2 != 0) return false;
        } else {
            if (freq[r] != freq[k - r]) return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (k == 0) return false;          // division by zero is not allowed
    int n = arr.length;
    if (n % 2 != 0) return false;      // need even number of elements to form pairs

    int[] freq = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;   // normalize remainder to [0, k-1]
        freq[r]++;
    }

    // Check remainder 0 group
    if (freq[0] % 2 != 0) return false;

    // If k is even, handle the special case where remainder == k/2
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) return false;
    }

    // For all other remainders, counts must match with complementary remainder
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) continue;      // already handled the k/2 case if needed
        if (freq[r] != freq[k - r]) return false;
    }

    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0 || k <= 0) {
        return false;
    }
    int[] freq = new int[k];
    for (int num : arr) {
        int mod = ((num % k) + k) % k; // ensure non-negative
        freq[mod]++;
    }
    // Check residue 0
    if (freq[0] % 2 != 0) {
        return false;
    }
    // If k even, check residue k/2
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) {
            return false;
        }
    }
    // Check remaining residues
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) { // already handled k even case; skip
            continue;
        }
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }
    return true;
}

