private int dfs(int node, int parent, List<List<Integer>> graph, boolean[] hasApple) {
    int time = 0;
    for (int child : graph.get(node)) {
        if (child == parent) continue;
        int subTime = dfs(child, node, graph, hasApple);
        if (subTime > 0 || hasApple[child]) {
            time += subTime + 2;
        }
    }
    return time;
}

