}
private int dfs(int node, List<Integer>[] adj, boolean[] visited, boolean[] hasApple) {
    visited[node] = true;
    int time = 0;
    for (int next : adj[node]) {
        if (!visited[next]) {
            int sub = dfs(next, adj, visited, hasApple);
            if (sub > 0 || hasApple[next]) {
                time += sub + 2;
            }
        }
    }
    return time;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<Integer>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
    for (int[] e : edges) {
        graph[e[0]].add(e[1]);
        graph[e[1]].add(e[0]);
    }
    int[] parent = new int[n];
    int[] order = new int[n];
    int idx = 0;
    Stack<Integer> st = new Stack<>();
    st.push(0);
    parent[0] = -1;
    while (!st.isEmpty()) {
        int node = st.pop();
        order[idx++] = node;
        for (int nei : graph[node]) {
            if (nei == parent[node]) continue;
            parent[nei] = node;
            st.push(nei);
        }
    }
    int[] need = new int[n];
    int total = 0;
    for (int i = n - 1; i >= 0; i--) {
        int node = order[i];
        boolean has = hasApple[node];
        for (int nei : graph[node]) {
            if (nei == parent[node]) continue;
            if (need[nei] > 0) {
                has = true;
                total += need[nei] + 2;
            }
        }
        need[node] = has ? 1 : 0;
    }
    return total;
}

