public String sortString(String s) {
    java.util.TreeMap<Character, Integer> map = new java.util.TreeMap<>();
    for (char c : s.toCharArray()) {
        map.merge(c, 1, Integer::sum);
    }
    java.lang.StringBuilder sb = new java.lang.StringBuilder();
    int remaining = s.length();
    while (remaining > 0) {
        // Ascending pass
        Character last = null;
        while (true) {
            Character c;
            if (last == null) {
                c = map.firstKey();
            } else {
                c = map.higherKey(last);
            }
            if (c == null) break;
            sb.append(c);
            int cnt = map.get(c);
            if (cnt == 1) {
                map.remove(c);
            } else {
                map.put(c, cnt - 1);
            }
            remaining--;
            last = c;
        }
        if (remaining == 0) break;

        // Descending pass
        Character lastDesc = null;
        Character c = map.lastKey();
        sb.append(c);
        int cnt = map.get(c);
        if (cnt == 1) {
            map.remove(c);
        } else {
            map.put(c, cnt - 1);
        }
        remaining--;
        lastDesc = c;
        while (true) {
            Character d = map.lowerKey(lastDesc);
            if (d == null) break;
            sb.append(d);
            int cntd = map.get(d);
            if (cntd == 1) {
                map.remove(d);
            } else {
                map.put(d, cntd - 1);
            }
            remaining--;
            lastDesc = d;
        }
    }
    return sb.toString();
}

public String sortString(String s) {
    int[] freq = new int[26];
    for (int i = 0; i < s.length(); i++) {
        freq[s.charAt(i) - 'a']++;
    }
    StringBuilder sb = new StringBuilder();
    int remaining = s.length();

    while (remaining > 0) {
        // Ascending sequence
        for (int i = 0; i < 26 && remaining > 0; i++) {
            if (freq[i] > 0) {
                sb.append((char) (i + 'a'));
                freq[i]--;
                remaining--;
                int last = i;
                while (true) {
                    int next = last + 1;
                    while (next < 26 && freq[next] == 0) {
                        next++;
                    }
                    if (next == 26) break;
                    sb.append((char) (next + 'a'));
                    freq[next]--;
                    remaining--;
                    last = next;
                }
                break;
            }
        }
        if (remaining == 0) break;

        // Descending sequence
        for (int i = 25; i >= 0 && remaining > 0; i--) {
            if (freq[i] > 0) {
                sb.append((char) (i + 'a'));
                freq[i]--;
                remaining--;
                int last = i;
                while (true) {
                    int next = last - 1;
                    while (next >= 0 && freq[next] == 0) {
                        next--;
                    }
                    if (next < 0) break;
                    sb.append((char) (next + 'a'));
                    freq[next]--;
                    remaining--;
                    last = next;
                }
                break;
            }
        }
    }
    return sb.toString();
}

public String sortString(String s) {
    TreeMap<Character, Integer> map = new TreeMap<>();
    for (char c : s.toCharArray()) {
        map.merge(c, 1, Integer::sum);
    }
    StringBuilder sb = new StringBuilder();
    while (!map.isEmpty()) {
        // Ascending phase
        Character cur = map.firstKey();
        while (cur != null) {
            sb.append(cur);
            int cnt = map.get(cur);
            if (cnt == 1) {
                map.remove(cur);
            } else {
                map.put(cur, cnt - 1);
            }
            cur = map.higherKey(cur);
        }
        if (map.isEmpty()) {
            break;
        }
        // Descending phase
        cur = map.lastKey();
        while (cur != null) {
            sb.append(cur);
            int cnt = map.get(cur);
            if (cnt == 1) {
                map.remove(cur);
            } else {
                map.put(cur, cnt - 1);
            }
            cur = map.lowerKey(cur);
        }
    }
    return sb.toString();
}

public String sortString(String s) {
    java.util.TreeMap<Character, Integer> freq = new java.util.TreeMap<>();
    for (char ch : s.toCharArray()) {
        freq.merge(ch, 1, Integer::sum);
    }
    StringBuilder result = new StringBuilder(s.length());
    int n = s.length();
    while (result.length() < n && !freq.isEmpty()) {
        // Ascending phase
        Character cur = freq.firstKey();
        result.append(cur);
        int cnt = freq.get(cur);
        if (cnt == 1) freq.remove(cur); else freq.put(cur, cnt - 1);
        Character last = cur;
        while (result.length() < n) {
            Character next = freq.higherKey(last);
            if (next == null) break;
            result.append(next);
            cnt = freq.get(next);
            if (cnt == 1) freq.remove(next); else freq.put(next, cnt - 1);
            last = next;
        }
        if (result.length() == n || freq.isEmpty()) break;

        // Descending phase
        cur = freq.lastKey();
        result.append(cur);
        cnt = freq.get(cur);
        if (cnt == 1) freq.remove(cur); else freq.put(cur, cnt - 1);
        last = cur;
        while (result.length() < n) {
            Character prev = freq.lowerKey(last);
            if (prev == null) break;
            result.append(prev);
            cnt = freq.get(prev);
            if (cnt == 1) freq.remove(prev); else freq.put(prev, cnt - 1);
            last = prev;
        }
    }
    return result.toString();
}

public String sortString(String s) {
