            } else {
                map.put(next, map.get(next) - 1);
            }
            prev = next;
        }
    }
    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int total = 0;
    for (int num : nums) total += num;
    // dp[k][s] indicates if there exists a subset of size k with sum s
    boolean[][] dp = new boolean[n + 1][total + 1];
    dp[0][0] = true;
    for (int num : nums) {
        // iterate k in reverse to avoid reuse of the same element
        for (int k = n - 1; k >= 1; k--) {
            for (int s = total; s >= num; s--) {
                if (dp[k - 1][s - num]) dp[k][s] = true;
            }
        }
    }
    for (int k = 1; k < n; k++) {
        // the average of the full array is total / n
        // we need total * k % n == 0 to be able to split
        if ((total * k) % n != 0) continue;
        int target = (total * k) / n;
        if (dp[k][target]) return true;
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
