    for (int v : nums) totalSum += v;
    @SuppressWarnings("unchecked")
    java.util.HashSet<Long>[] dp = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) dp[i] = new java.util.HashSet<>();
    dp[0].add(0L);
    for (int num : nums) {
        for (int k = n - 1; k >= 0; k--) {
            if (dp[k].isEmpty()) continue;
            for (Long s : dp[k]) {
                dp[k + 1].add(s + num);
            }
        }
    }
    for (int k = 1; k < n; k++) {
        if ((totalSum * k) % n != 0) continue;
        long target = (totalSum * k) / n;
        if (dp[k].contains(target)) return true;
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) {
        return false;
    }
    int total = 0;
    for (int num : nums) {
        total += num;
    }

    // dp[k] contains all possible sums of subsets with size k
    @SuppressWarnings("unchecked")
    List<HashSet<Integer>> dp = new ArrayList<>(n + 1);
    for (int i = 0; i <= n; i++) {
        dp.add(new HashSet<>());
    }
    dp.get(0).add(0);

    for (int num : nums) {
        // traverse sizes in reverse to avoid using the current number more than once
        for (int k = n - 1; k >= 1; k--) {
            Set<Integer> prevSet = dp.get(k - 1);
            Set<Integer> curSet = dp.get(k);
            for (int sum : prevSet) {
                curSet.add(sum + num);
            }
        }
    }

    for (int k = 1; k < n; k++) {
        if ((total * k) % n != 0) {
            continue;
        }
        int target = (total * k) / n;
        if (dp.get(k).contains(target)) {
            return true;
        }
    }
    return false;
}

