public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int prev2 = 0; // dp[i-2]
    int prev1 = 0; // dp[i-1]
    for (int i = 2; i <= n; i++) {
        int cur = cost[i - 1] + Math.min(prev1, prev2);
        prev2 = prev1;
        prev1 = cur;
    }
    return prev1;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    int prevPrev = cost[0];
    int prev = cost[1];
    for (int i = 2; i < n; i++) {
        int cur = cost[i] + Math.min(prev, prevPrev);
        prevPrev = prev;
        prev = cur;
    }
    return Math.min(prev, prevPrev);
}

