        prev2 = prev1;
        prev1 = curr;
    }
    return Math.min(prev1, prev2);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n <= 1) return 0;
    int oneStepBack = 0; // dp[i-1]
    int twoStepsBack = 0; // dp[i-2]
    for (int i = 2; i <= n; i++) {
        int current = Math.min(oneStepBack + cost[i - 1], twoStepsBack + cost[i - 2]);
        twoStepsBack = oneStepBack;
        oneStepBack = current;
    }
    return oneStepBack;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return cost[0];
    }

    int prev2 = cost[0];
    int prev1 = cost[1];

    for (int i = 2; i < n; i++) {
        int current = cost[i] + Math.min(prev1, prev2);
        prev2 = prev1;
        prev1 = current;
    }

    return Math.min(prev1, prev2);
}

