public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    if (k == 0) return true;          // empty string trivially present
    if (n < k) return false;

    int totalCodes = 1 << k;
    boolean[] seen = new boolean[totalCodes];
    int seenCount = 0;
    int mask = 0;
    int maskLimit = totalCodes - 1;   // (1<<k) - 1

    for (int i = 0; i < n; i++) {
        // Update sliding window mask
        mask = ((mask << 1) & maskLimit) | (s.charAt(i) - '0');
        if (i < k - 1) continue;     // Need at least k characters to form a code

        if (!seen[mask]) {
            seen[mask] = true;
            seenCount++;
            if (seenCount == totalCodes) return true; // All codes found
        }
    }
    return false;
}

