public int minOperations(int n) {
    if (n % 2 == 0) {
        int k = n / 2;
        return k * k;
    } else {
        int k = n / 2; // floor((n-1)/2)
        return k * (k + 1);
    }
}

public int minOperations(int n) {
    long m = n;
    long start = (m % 2 == 0) ? m / 2 : m / 2 + 1;
    long t = m - start;
    if (t <= 0) return 0;
    long sumI = (start + (m - 1)) * t / 2;
    long operations = 2 * sumI + t - m * t;
    return (int) operations;
}

public int minOperations(int n) {
    int start = (n - 1) / 2 + 1;
    int m = n - start;
    return m * start;
}

public int minOperations(int n) {
    int operations = 0;
    for (int i = 0; i < n; i++) {
        int value = 2 * i + 1;
        int diff = value - n;
        if (diff > 0) {
            operations += diff;
        }
    }
    return operations;
}

public int minOperations(int n) {
    if (n % 2 == 0) {
        return n * n / 4;
    } else {
        return (n * n - 1) / 4;
    }
}

