public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to k
    java.util.ArrayList<Integer> fib = new java.util.ArrayList<>();
    fib.add(1);
    fib.add(1);
    while (fib.get(fib.size() - 1) + fib.get(fib.size() - 2) <= k) {
        int next = fib.get(fib.size() - 1) + fib.get(fib.size() - 2);
        fib.add(next);
    }

    int count = 0;
    int remaining = k;
    // Greedy: subtract the largest Fibonacci number <= remaining
    for (int i = fib.size() - 1; i >= 0 && remaining > 0; i--) {
        int f = fib.get(i);
        if (f <= remaining) {
            remaining -= f;
            count++;
        }
    }
    return count;
}

public int findMinFibonacciNumbers(int k) {
    // Generate all Fibonacci numbers not exceeding k
    List<Integer> fibs = new ArrayList<>();
    fibs.add(1);
    fibs.add(1);
    while (true) {
        int size = fibs.size();
        long next = (long) fibs.get(size - 1) + fibs.get(size - 2);
        if (next > k) break;
        fibs.add((int) next);
    }

    int count = 0;
    int remaining = k;
    // Greedy subtraction using the largest possible Fibonacci number each time
    while (remaining > 0) {
        int idx = binarySearchLargest(fibs, remaining);
        int fibVal = fibs.get(idx);
        remaining -= fibVal;
        count++;
    }
    return count;
}

// Helper method: binary search to find largest Fibonacci number <= target
private int binarySearchLargest(List<Integer> fibs, int target) {
    int low = 0, high = fibs.size() - 1;
    while (low <= high) {
        int mid = (low + high) >>> 1;
        if (fibs.get(mid) <= target) {
            if (mid == fibs.size() - 1 || fibs.get(mid + 1) > target)
                return mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return 0; // fallback (should not happen for k >= 1)
}

