public int kthFactor(int n, int k) {
    java.util.ArrayList<Integer> factors = new java.util.ArrayList<>();
    int sqrt = (int)Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            factors.add(i);
            int other = n / i;
            if (other != i) {
                factors.add(other);
            }
        }
    }
    java.util.Collections.sort(factors);
    if (k - 1 < factors.size()) {
        return factors.get(k - 1);
    } else {
        return -1;
    }
}

public int kthFactor(int n, int k) {
    if (k <= 0) return -1;
    List<Integer> small = new ArrayList<>();
    List<Integer> large = new ArrayList<>();
    int sqrt = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small.add(i);
            int other = n / i;
            if (other != i) large.add(other);
        }
    }
    int total = small.size() + large.size();
    if (k > total) return -1;
    if (k <= small.size()) {
        return small.get(k - 1);
    } else {
        int idx = k - small.size() - 1; // zero‑based index in reversed large
        return large.get(large.size() - 1 - idx);
    }
}

public int kthFactor(int n, int k) {
    java.util.List<Integer> lower = new java.util.ArrayList<>();
    java.util.List<Integer> higher = new java.util.ArrayList<>();
    int sqrt = (int)Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            lower.add(i);
            if (i != n / i) {
                higher.add(n / i);
            }
        }
    }
    java.util.Collections.reverse(higher);
    int count = 0;
    for (int val : lower) {
        count++;
        if (count == k) return val;
    }
    for (int val : higher) {
        count++;
        if (count == k) return val;
    }
    return -1;
}

public int kthFactor(int n, int k) {
    List<Integer> small = new ArrayList<>();
    List<Integer> large = new ArrayList<>();
    int limit = (int) Math.sqrt(n);
    for (int i = 1; i <= limit; i++) {
        if (n % i == 0) {
            small.add(i);
            int other = n / i;
            if (other != i) {
                large.add(other);
            }
        }
    }
    // Build the sorted list of factors
    int total = small.size() + large.size();
    if (k > total) {
        return -1;
    }
    if (k <= small.size()) {
        return small.get(k - 1);
    }
    // For factors beyond the small-range, we need to consider reversed order of large
    // large list is in descending order relative to the ascending factor order for the second half
    int indexInLarge = k - small.size() - 1;
    // large list currently stored in the same order they were found, which is ascending (since we added when found).
    // But they are actually descending when sorted ascending: e.g., if n=12, large = [12] after loop. 
    // Wait: we added large when i=1 -> other=12; i=2 -> other=6; i=3 -> other=4. That is [12,6,4] descending. So we need to reverse before using.
    // We'll retrieve by reversing index.
    return large.get(large.size() - 1 - indexInLarge);
}

public int kthFactor(int n, int k) {
    java.util.List<Integer> small = new java.util.ArrayList<>();
    java.util.List<Integer> large = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            small.add(i);
            if (i != n / i) {
                large.add(n / i);
            }
        }
    }
    java.util.Collections.reverse(large);
    int total = small.size() + large.size();
    if (k > total) {
        return -1;
    }
    if (k <= small.size()) {
        return small.get(k - 1);
    } else {
        return large.get(k - 1 - small.size());
    }
}

public String makeGood(String s) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int len = sb.length();
        if (len > 0) {
            char last = sb.charAt(len - 1);
            if (last != c && Math.abs(last - c) == 32) {
                sb.setLength(len - 1);
                continue;
            }
        }
        sb.append(c);
    }
    return sb.toString();
}

