public int maxUniqueSplit(String s) {
    int[] max = {0};
    dfs(0, s, new HashSet<>(), 0, max);
    return max[0];
}

private void dfs(int index, String s, Set<String> seen, int count, int[] max) {
    if (index == s.length()) {
        if (count > max[0]) {
            max[0] = count;
        }
        return;
    }
    for (int end = index + 1; end <= s.length(); end++) {
        String sub = s.substring(index, end);
        if (!seen.contains(sub)) {
            seen.add(sub);
            dfs(end, s, seen, count + 1, max);
            seen.remove(sub);
        }
    }
}

