        boolean ok = true; 
        for (int i = 0; i < n - 1; i++) { 
            if ((mask & (1 << i)) != 0) { 
                String sub = s.substring(last, i + 1); 
                if (!set.add(sub)) { 
                    ok = false; 
                    break; 
                } 
                last = i + 1; 
            } 
        } 
        if (!ok) continue; 
        String sub = s.substring(last); 
        if (!set.add(sub)) continue; 
        max = Math.max(max, set.size()); 
    } 
    return max; 
}

public int maxUniqueSplit(String s) {
