private int dfs(int pos, String s, java.util.Set<String> used) {
    if (pos == s.length()) return 0;
    int best = 0;
    for (int end = pos + 1; end <= s.length(); end++) {
        String sub = s.substring(pos, end);
        if (used.contains(sub)) continue;
        used.add(sub);
        int val = 1 + dfs(end, s, used);
        if (val > best) best = val;
        used.remove(sub);
    }
    return best;
}

public int maxUniqueSplit(String s) {
