}
private int dfs(String s, java.util.Set<String> used) {
    if (s.isEmpty()) {
        return 0;
    }
    int best = 0;
    for (int i = 1; i <= s.length(); i++) {
        String part = s.substring(0, i);
        if (!used.contains(part)) {
            used.add(part);
            int current = 1 + dfs(s.substring(i), used);
            if (current > best) best = current;
            used.remove(part);
        }
    }
    return best;
}

public int maxUniqueSplit(String s) {
