}

private int dfs(String s, int pos, java.util.Set<String> seen) {
    if (pos == s.length()) {
        return 0;
    }
    int max = 0;
    for (int end = pos + 1; end <= s.length(); end++) {
        String part = s.substring(pos, end);
        if (!seen.contains(part)) {
            seen.add(part);
            int cur = 1 + dfs(s, end, seen);
            if (cur > max) {
                max = cur;
            }
            seen.remove(part);
        }
    }
    return max;
}

