public String getSmallestString(int n, int k) {
    char[] res = new char[n];
    for (int i = 0; i < n; i++) {
        res[i] = 'a';
    }
    int remaining = k - n;
    int i = n - 1;
    while (remaining > 0 && i >= 0) {
        int add = Math.min(25, remaining);
        res[i] = (char) ('a' + add);
        remaining -= add;
        i--;
    }
    return new String(res);
}

public String getSmallestString(int n, int k) {
    if (n <= 0) {
        return "";
    }
    // Minimum possible sum is n (all 'a'), maximum is 26*n (all 'z')
    if (k < n || k > 26 * n) {
        throw new IllegalArgumentException("k is out of valid range");
    }

    char[] arr = new char[n];
    java.util.Arrays.fill(arr, 'a'); // start with all 'a'
    int remaining = k - n; // additional value needed over all 'a's

    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int increment = Math.min(25, remaining); // we can add up to 25 extra per position
        arr[i] = (char) ('a' + increment);
        remaining -= increment;
    }

    return new String(arr);
}

