                diagCurr[j] = (j > 0 ? diagPrev[j - 1] : 0) + 1;
                antiCurr[j] = (j + 1 < n ? antiPrev[j + 1] : 0) + 1;
                int localMax = Math.max(Math.max(horiz, vert[j]), Math.max(diagCurr[j], antiCurr[j]));
                if (localMax > maxLen) {
                    maxLen = localMax;
                }
            } else {
                horiz = 0;
                vert[j] = 0;
                diagCurr[j] = 0;
                antiCurr[j] = 0;
            }
        }
        diagPrev = diagCurr;
        antiPrev = antiCurr;
    }
    return maxLen;
}

