        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                horiz[i][j] = (j > 0) ? horiz[i][j - 1] + 1 : 1;
                vert[i][j] = (i > 0) ? vert[i - 1][j] + 1 : 1;
                diag[i][j] = (i > 0 && j > 0) ? diag[i - 1][j - 1] + 1 : 1;
                anti[i][j] = (i > 0 && j < n - 1) ? anti[i - 1][j + 1] + 1 : 1;
                int localMax = Math.max(Math.max(horiz[i][j], vert[i][j]), Math.max(diag[i][j], anti[i][j]));
                if (localMax > max) {
                    max = localMax;
                }
            } else {
                horiz[i][j] = 0;
                vert[i][j] = 0;
                diag[i][j] = 0;
                anti[i][j] = 0;
            }
        }
    }
    return max;
}

