public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 1;
    // Precompute adjacency: whether sum of A[i]+A[j] is a perfect square
    boolean[][] adj = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            int sum = A[i] + A[j];
            int root = (int) Math.sqrt(sum);
            adj[i][j] = (root * root == sum);
        }
    }
    int maxMask = 1 << n;
    long[][] dp = new long[maxMask][n];
    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 1; // start with each element
    }
    for (int mask = 1; mask < maxMask; mask++) {
        for (int last = 0; last < n; last++) {
            long ways = dp[mask][last];
            if (ways == 0) continue;
            int remaining = (~mask) & (maxMask - 1);
            while (remaining != 0) {
                int next = Integer.numberOfTrailingZeros(remaining);
                remaining &= remaining - 1; // remove lowest set bit
                if (adj[last][next]) {
                    dp[mask | (1 << next)][next] += ways;
                }
            }
        }
    }
    long total = 0;
    int fullMask = maxMask - 1;
    for (int last = 0; last < n; last++) {
        total += dp[fullMask][last];
    }
    return (int) total;
}

