public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int total = m * n;
    int[] result = new int[total];
    int idx = 0;
    for (int sum = 0; sum <= m + n - 2; sum++) {
        int start = Math.max(0, sum - (n - 1));
        int end = Math.min(m - 1, sum);
        if (sum % 2 == 0) {
            for (int i = end; i >= start; i--) {
                int j = sum - i;
                result[idx++] = mat[i][j];
            }
        } else {
            for (int i = start; i <= end; i++) {
                int j = sum - i;
                result[idx++] = mat[i][j];
            }
        }
    }
    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int[] res = new int[m * n];
    int idx = 0;
    int maxSum = m + n - 2;
    for (int sum = 0; sum <= maxSum; sum++) {
        if ((sum & 1) == 0) { // even sum: go from bottom to top
            int r = Math.min(sum, m - 1);
            int c = sum - r;
            while (r >= 0 && c < n) {
                res[idx++] = mat[r][c];
                r--;
                c++;
            }
        } else { // odd sum: go from top to bottom
            int c = Math.min(sum, n - 1);
            int r = sum - c;
            while (c >= 0 && r < m) {
                res[idx++] = mat[r][c];
                r++;
                c--;
            }
        }
    }
    return res;
}

