    for (int i = 0; i < m * n; i++) {
        res[i] = mat[row][col];
        if (up) {
            if (col == n - 1) {       // hit the right boundary
                row++;
                up = false;
            } else if (row == 0) {    // hit the top boundary
                col++;
                up = false;
            } else {
                row--;
                col++;
            }
        } else {
            if (row == m - 1) {       // hit the bottom boundary
                col++;
                up = true;
            } else if (col == 0) {    // hit the left boundary
                row++;
                up = true;
            } else {
                row++;
                col--;
            }
        }
    }
    return res;
}

