            if (pos == n - pos - 1) {
                for (char c : new char[]{'0', '1', '8'}) {
                    arr[pos] = c;
                    res.add(new String(arr));
                }
                return;
            }
            for (char left : new char[]{'0', '1', '6', '8', '9'}) {
                if (pos == 0 && n > 1 && left == '0') continue;
                char right = map(left);
                arr[pos] = left;
                arr[n - pos - 1] = right;
                build(pos + 1);
            }
        }
        char map(char d) {
            switch (d) {
                case '0': return '0';
                case '1': return '1';
                case '6': return '9';
                case '8': return '8';
                case '9': return '6';
                default: return '0';
            }
        }
    }
    new Builder().build(0);
    return res;
}

