    if (currentLen == 1) {
        res.add("0");
        res.add("1");
        res.add("8");
        return res;
    }
    List<String> inner = generate(currentLen - 2, totalLen);
    for (String innerStr : inner) {
        // Pair 0-0
        if (!(currentLen == totalLen && '0' == '0')) {
            // We'll skip leading zero only when outermost
        }
        if (!(currentLen == totalLen && '0' == '0')) {
            // this pair is allowed only if not outermost
        }
    }
    // set of pairs
    char[][] pairs = { {'0', '0'}, {'1', '1'}, {'6', '9'}, {'8', '8'}, {'9', '6'} };
    for (String innerStr : inner) {
        for (char[] p : pairs) {
            if (currentLen == totalLen && p[0] == '0') {
