public static java.util.List<String> centerSymmetricNumbers(int n) {
    java.util.List<String> result = new java.util.ArrayList<>();
    if (n <= 0) {
        return result;
    }
    char[][] pairs = {{'0','0'}, {'1','1'}, {'6','9'}, {'8','8'}, {'9','6'}};
    char[] current = new char[n];

    java.util.function.Consumer<int[]> builder = new java.util.function.Consumer<int[]>() {
        @Override
        public void accept(int[] positions) {
            int left = positions[0];
            int right = positions[1];
            if (left > right) {
                result.add(new String(current));
                return;
            }
            if (left == right) {
                for (char mid : new char[] {'0', '1', '8'}) {
                    current[left] = mid;
                    accept(new int[]{left + 1, right - 1});
                }
            } else {
                for (char[] pair : pairs) {
                    if (left == 0 && pair[0] == '0') {
                        continue;
                    }
                    current[left] = pair[0];
                    current[right] = pair[1];
                    accept(new int[]{left + 1, right - 1});
                }
            }
        }
    };
    builder.accept(new int[]{0, n - 1});
    return result;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    // Ensure all points are distinct
    if ((points[0][0] == points[1][0] && points[0][1] == points[1][1]) ||
        (points[0][0] == points[2][0] && points[0][1] == points[2][1]) ||
        (points[1][0] == points[2][0] && points[1][1] == points[2][1])) {
        return false;
    }
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];
    // Check if points are not collinear using the cross product
    int cross = (x2 - x1) * (y3 - y1) - (y2 - y1) * (x3 - x1);
    return cross != 0;
}

