public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int min = Integer.MAX_VALUE;
        for (int s = 1; s * s <= i; s++) {
            int square = s * s;
            int value = dp[i - square] + 1;
            if (value < min) {
                min = value;
            }
        }
        dp[i] = min;
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) return 0;
    int INF = n + 1; // A value greater than any possible number of squares
    int[] dp = new int[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = INF;
    }
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            if (dp[i - square] + 1 < dp[i]) {
                dp[i] = dp[i - square] + 1;
            }
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        dp[i] = i; // maximum possible
        for (int j = 1; j * j <= i; j++) {
            int sq = j * j;
            int candidate = dp[i - sq] + 1;
            if (candidate < dp[i]) {
                dp[i] = candidate;
            }
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) return 0;
    // Precompute all perfect squares <= n
    int maxRoot = (int) Math.sqrt(n);
    int[] squares = new int[maxRoot];
    for (int i = 1; i <= maxRoot; i++) {
        squares[i - 1] = i * i;
    }
    // DP array: dp[i] = min number of squares summing to i
    int[] dp = new int[n + 1];
    java.util.Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0; // base case
    for (int i = 1; i <= n; i++) {
        for (int sq : squares) {
            if (sq > i) break;
            if (dp[i - sq] != Integer.MAX_VALUE) {
                dp[i] = Math.min(dp[i], dp[i - sq] + 1);
            }
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) return 0;
    int sqrtN = (int) Math.sqrt(n);
    if (sqrtN * sqrtN == n) return 1;
    for (int i = 1; i <= sqrtN; i++) {
        int rem = n - i * i;
        int sqrtRem = (int) Math.sqrt(rem);
        if (sqrtRem * sqrtRem == rem) return 2;
    }
    int temp = n;
    while (temp % 4 == 0) temp /= 4;
    if (temp % 8 == 7) return 4;
    return 3;
}

